// R5: rounds to 0 becomes 1
assert.deepEqual(retrySchedule({retries:1,baseMs:0.4,factor:1,maxMs:10,jitter:'none'}), [1]);
assert.deepEqual(retrySchedule({retries:1,baseMs:1,factor:1,maxMs:10,jitter:'full'}, () => 0.01), [1]);

